use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Helper function to format potentially truncated output for stdout or stderr"] fn tag_output (lines : Vec < String > , truncation_info : Option < (usize , usize) > , total_lines : usize , truncated_lines_count : usize ,) -> FormattedOutput { match truncation_info { Some ((prefix_count , hidden_count)) => { let suffix_start_line = prefix_count + hidden_count + 1 ; let mut head = String :: new () ; let mut tail = String :: new () ; for line in lines . iter () . take (prefix_count) { head . push_str (line) ; head . push ('\n') ; } for line in lines . iter () . skip (prefix_count) { tail . push_str (line) ; tail . push ('\n') ; } FormattedOutput { head , tail : if tail . is_empty () { None } else { Some (tail) } , suffix_start_line : Some (suffix_start_line) , suffix_end_line : Some (total_lines) , prefix_end_line : prefix_count , truncated_lines_count , } } None => { let mut content = String :: new () ; for (i , line) in lines . iter () . enumerate () { content . push_str (line) ; if i < lines . len () - 1 { content . push ('\n') ; } } FormattedOutput { head : content , tail : None , suffix_start_line : None , suffix_end_line : None , prefix_end_line : total_lines , truncated_lines_count , } } } }